contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single test function driving getTokens with an ETH value amount
    function run(uint256 sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= sendAmount);

        // read observable state before the call
        uint256 beforeBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        bool beforeBlacklisted = c.blacklist(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractEthBefore = address(c).balance;

        // perform the call and capture whether it reverted
        bool reverted;
        c.getTokens{value: sendAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read observable state after the call
        uint256 afterBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        bool afterBlacklisted = c.blacklist(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractEthAfter = address(c).balance;

        // General rule:
        // If call succeeded (not reverted) then:
        //  - afterBalance == beforeBalance + (afterTotalDistributed - beforeTotalDistributed)
        //  - afterTotalDistributed >= beforeTotalDistributed
        //  - afterBlacklisted == true
        //  - contract's ETH increased by sendAmount
        // If call reverted then no observable changes to c's public state or balance should have occurred.
        assert(
            reverted
            ? (
                afterBalance == beforeBalance
                && afterTotalDistributed == beforeTotalDistributed
                && afterBlacklisted == beforeBlacklisted
                && contractEthAfter == contractEthBefore
              )
            : (
                afterTotalDistributed >= beforeTotalDistributed
                && afterBalance == beforeBalance + (afterTotalDistributed - beforeTotalDistributed)
                && afterBlacklisted == true
                && contractEthAfter == contractEthBefore + sendAmount
              )
        );
    }

    // allow receiving ETH so tests can fund this contract
    receive() external payable {}
}

