pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint256 beforeBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint256 beforeTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { beforeTotalDistributed = __r; } catch { return; }
        bool beforeBlacklisted;
        try c.blacklist(address(this)) returns (bool __r) { beforeBlacklisted = __r; } catch { return; }
        uint256 contractEthBefore = address(c).balance;
        bool reverted;
        try c.getTokens{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        uint256 afterTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { afterTotalDistributed = __r; } catch { return; }
        bool afterBlacklisted;
        try c.blacklist(address(this)) returns (bool __r) { afterBlacklisted = __r; } catch { return; }
        uint256 contractEthAfter = address(c).balance;
        assertTrue(reverted
            ? (
                afterBalance == beforeBalance
                && afterTotalDistributed == beforeTotalDistributed
                && afterBlacklisted == beforeBlacklisted
                && contractEthAfter == contractEthBefore
              )
            : (
                afterTotalDistributed >= beforeTotalDistributed
                && afterBalance == beforeBalance + (afterTotalDistributed - beforeTotalDistributed)
                && afterBlacklisted == true
                && contractEthAfter == contractEthBefore + sendAmount
              ));
    }

    function testFuzz_run(uint256 sendAmount) public {
        _run(sendAmount);
    }

    receive() external payable {}
}
